import json
import csv

with open('/app/parent_map.json', 'r', encoding='utf-8') as f:
    parent_map = json.load(f)

csv_names = []
accounts = {}
with open('/app/dataset/people_accounts.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    next(reader)
    for row in reader:
        name = f"{row[0]} {row[1]}"
        csv_names.append(name)
        accounts[name] = int(row[2])

def match_name(parsed_name):
    if not parsed_name: return None
    if parsed_name in csv_names:
        return parsed_name
    p_no_space = parsed_name.replace(" ", "")
    for cn in csv_names:
        if p_no_space == cn.replace(" ", ""):
            return cn
    for cn in csv_names:
        if cn in parsed_name or parsed_name in cn:
            return cn
    p_words = set(parsed_name.split())
    for cn in csv_names:
        c_words = set(cn.split())
        if len(p_words.intersection(c_words)) >= 2:
            return cn
    return parsed_name

clean_parent_map = {}
for child, parent in parent_map.items():
    clean_parent_map[child] = match_name(parent)

# build children map
children_map = {name: [] for name in csv_names}
for child, parent in clean_parent_map.items():
    if parent in children_map:
        children_map[parent].append(child)
    else:
        children_map[parent] = [child]

# Find Przemysław Kurczab
target = "Przemysław Kurczab"

direct_children = children_map.get(target, [])
print(f"Direct children of {target}: {direct_children}")

total_sum = 0
for child in direct_children:
    # count grandchildren
    grandchildren_count = 0
    for grand in children_map.get(child, []):
        grandchildren_count += len(children_map.get(grand, []))

    print(f"Child {child} has {grandchildren_count} grandchildren.")
    if grandchildren_count > 1:
        bal = accounts[child]
        print(f" -> Adding balance {bal}")
        total_sum += bal

print(f"Total sum: {total_sum}")

